import json

LIMIT = 200  # search bound for primes (exhaustive within this range only)

def primes_upto(n):
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    return [i for i in range(n + 1) if sieve[i]]

ps = primes_upto(LIMIT)
found = []
checked = 0
min_D = None

for p in ps:
    for q in ps:
        if q >= p:
            continue
        a = p + q          # >= 5
        b = p - q          # >= 1
        N = a ** a * b ** b - 1
        D = a ** b * b ** a - 1
        checked += 1
        if D <= 0:
            continue
        if min_D is None or D < min_D:
            min_D = D
        if N % D == 0:
            found.append((p, q, N // D))

pairs = [(p, q) for p, q, _ in found]
final_answer = "(p,q) = " + ", ".join(f"({p},{q})" for p, q in pairs) if pairs else "none"

result = {
    "final_answer": final_answer,
    "evidence": {
        "search_bound_prime_limit": LIMIT,
        "pairs_checked": checked,
        "pairs_found": [{"p": p, "q": q, "quotient": str(qt)} for p, q, qt in found],
        "scope_note": "Exhaustive exact-integer check only for primes <= LIMIT; "
                      "this does not by itself prove the result for all primes.",
        "method": "exact big-integer arithmetic, divisibility test N % D == 0 with a=p+q, b=p-q",
    },
}

print(json.dumps(result, indent=2))
